<script setup lang="ts">
import { ref,watch,onBeforeUnmount } from 'vue';
import { api,errorText,socketUrl } from './api';
import { bindingKeys,sameRunBinding,viewportPoint } from './transport';
const props=withDefaults(defineProps<{sessionId?:string;runId?:string;projectId:string;interactive?:boolean}>(),{interactive:false});
const emit=defineEmits<{error:[message:string];event:[event:any]}>();
const canvas=ref<HTMLCanvasElement>();const streamState=ref('waiting');const lastFrame=ref<any>();const pages=ref<{id:string;url:string}[]>([]);
let ws:WebSocket|undefined,header:any,waiting:{header:any;bytes:ArrayBuffer}|undefined,processing=false,disposed=false,generation=0,lastAt=0,currentBinding:any;
function clear(){if(ws){ws.close();ws=undefined;}header=undefined;waiting=undefined;generation++;streamState.value='waiting';lastFrame.value=undefined;pages.value=[];if(canvas.value){canvas.value.getContext('2d')?.clearRect(0,0,canvas.value.width,canvas.value.height);for(const k of [...bindingKeys,'frameSha256'])delete (canvas.value.dataset as any)[k];}}
function pageEvent(event:any){if(event.type==='browser.pageClosed')pages.value=pages.value.filter(p=>p.id!==event.pageId);else if(event.pageId){const known=pages.value.find(p=>p.id===event.pageId);if(known&&event.payload?.url)known.url=event.payload.url;else if(!known)pages.value.push({id:event.pageId,url:event.payload?.url??''});}emit('event',event);}
watch(()=>props.sessionId,id=>{clear();if(!id)return;ws=new WebSocket(socketUrl(`/browser-sessions/${encodeURIComponent(id)}`));ws.binaryType='arraybuffer';ws.onopen=()=>streamState.value='connected';ws.onmessage=event=>{if(typeof event.data==='string'){let message:any;try{message=JSON.parse(event.data);}catch{return;}if(message.type==='browser.frame')header=message;else if(message.type==='error'||message.type==='browser.error'){streamState.value='error';emit('error',message.message??message.payload?.message??'瀏覽器執行失敗');}else pageEvent(message);}else if(header){const h=header;header=undefined;present(h,event.data);}};ws.onerror=()=>{streamState.value='error';emit('error','瀏覽器串流連線失敗');};ws.onclose=()=>{streamState.value='closed';};},{immediate:true});
watch(()=>props.runId,()=>{if(props.sessionId)return;generation++;waiting=undefined;streamState.value=props.runId?'waiting':'not_bound';});
async function present(h:any,bytes:ArrayBuffer){if(disposed)return;if(props.runId&&h.runId!==props.runId)return;if(props.sessionId&&h.sessionId!==props.sessionId)return;waiting={header:h,bytes};if(processing)return;processing=true;try{while(waiting&&!disposed){const current=waiting;waiting=undefined;const frameGeneration=generation;const frame=current.header;const expected=frame.payload?.sha256??frame.payload?.frameSha256;
  if(!expected){emit('error','畫格缺少 SHA-256，已拒絕呈現');continue;}
  const digest=await crypto.subtle.digest('SHA-256',current.bytes);const actual=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');if(actual!==expected){emit('error','畫格 SHA-256 不一致，已拒絕呈現');continue;}
  if(props.runId){if(currentBinding&&!sameRunBinding(frame,currentBinding))continue;const binding=await api(`/runs/${encodeURIComponent(props.runId)}/viewer-binding`);if(!sameRunBinding(frame,binding))continue;}
  const image=await createImageBitmap(new Blob([current.bytes],{type:'image/jpeg'}));if(frameGeneration!==generation||disposed||(props.runId&&frame.runId!==props.runId)){image.close();continue;}
  const el=canvas.value;if(!el){image.close();continue;}el.width=image.width;el.height=image.height;const context=el.getContext('2d');if(!context){image.close();throw Error('此瀏覽器無法建立 canvas 2D 畫布，未呈現畫格');}context.drawImage(image,0,0);image.close();
  for(const key of bindingKeys){if(frame[key]!==undefined)(el.dataset as any)[key]=String(frame[key]);else delete (el.dataset as any)[key];}el.dataset.frameSha256=actual;if(props.interactive&&!pages.value.some(p=>p.id===frame.pageId))pages.value.push({id:frame.pageId,url:''});lastFrame.value=frame;lastAt=Date.now();streamState.value='live';
 }}catch(error){streamState.value='error';emit('error',errorText(error));}finally{processing=false;}}
function send(message:any){if(!props.interactive)return;if(!ws||ws.readyState!==WebSocket.OPEN){emit('error','瀏覽器尚未連線，輸入未送出');return;}ws.send(JSON.stringify({pageId:lastFrame.value?.pageId,contextRef:lastFrame.value?.contextRef,...message}));}
function pointer(event:PointerEvent,action:string){if(!props.interactive||!canvas.value||!lastFrame.value)return;const bounds=canvas.value.getBoundingClientRect(),payload=lastFrame.value.payload;const point=viewportPoint(bounds,{width:payload.viewportWidth??canvas.value.width,height:payload.viewportHeight??canvas.value.height},{x:event.clientX,y:event.clientY});if(!point)return;canvas.value.focus();send({type:'pointer',action,...point,button:['left','middle','right'][event.button]??'left'});}
function keyboard(event:KeyboardEvent,action:string){if(!props.interactive||event.isComposing||['Process','Dead'].includes(event.key))return;event.preventDefault();if(event.key.length===1&&!event.ctrlKey&&!event.metaKey&&!event.altKey){if(action==='down')send({type:'text',text:event.key});return;}send({type:'key',action,key:event.key,code:event.code,modifiers:[event.ctrlKey?'Control':null,event.metaKey?'Meta':null,event.shiftKey?'Shift':null,event.altKey?'Alt':null].filter(Boolean)});}
function wheel(event:WheelEvent){if(!props.interactive)return;event.preventDefault();send({type:'wheel',deltaX:event.deltaX,deltaY:event.deltaY});}
function selectPage(pageId:string){send({type:'activatePage',pageId});generation++;waiting=undefined;lastFrame.value=undefined;streamState.value='waiting';}
function navigate(url:string){send({type:'navigate',url});}
function ended(){generation++;waiting=undefined;streamState.value='ended';}
function bind(binding:any){if(binding.runId!==props.runId)return;if(currentBinding&&sameRunBinding(binding,currentBinding))return;currentBinding=binding;generation++;waiting=undefined;lastFrame.value=undefined;streamState.value='waiting';if(canvas.value)delete canvas.value.dataset.frameSha256;}
function started(){currentBinding=undefined;generation++;waiting=undefined;lastFrame.value=undefined;streamState.value='waiting';if(canvas.value)delete canvas.value.dataset.frameSha256;}
const timer=window.setInterval(()=>{if(streamState.value==='live'&&Date.now()-lastAt>8000)streamState.value='waiting';},1000);
onBeforeUnmount(()=>{disposed=true;clear();clearInterval(timer);});
defineExpose({present,navigate,ended,bind,started});
</script>
<template><div class="browser-view"><div v-if="interactive&&pages.length" class="browser-tabs"><button v-for="p in pages" :key="p.id" class="browser-tab" :class="{active:lastFrame?.pageId===p.id}" :title="p.url||p.id" @click="selectPage(p.id)">{{p.url||'分頁 · '+p.id.slice(0,6)}}</button></div><div class="stream-bar"><span class="status-dot" :class="{live:streamState==='live'}"></span><span :data-testid="interactive?'browser-stream-state':'run-stream-state'">{{streamState}}</span><span class="stream-kind">{{interactive?'同會話 · 可操作':'目前測試 · 即時畫面'}}</span></div><div class="canvas-stage"><canvas ref="canvas" :data-testid="interactive?'browser-canvas':'run-browser-canvas'" tabindex="0" aria-label="遠端瀏覽器即時畫面" @pointerdown.prevent="pointer($event,'down')" @pointerup.prevent="pointer($event,'up')" @keydown="keyboard($event,'down')" @keyup="keyboard($event,'up')" @wheel="wheel" @contextmenu.prevent></canvas><div v-if="!lastFrame" class="canvas-placeholder"><span class="placeholder-icon">▣</span><strong>{{runId?'等待目前測試綁定頁面':'尚未收到瀏覽器畫格'}}</strong><p>只呈現真實會話的 JPEG 串流</p></div></div><div class="binding-meta"><span :data-testid="interactive?'browser-session-id':'run-session-id'">{{sessionId||lastFrame?.sessionId||'未綁定'}}</span><span v-if="lastFrame?.testKey">{{lastFrame.testKey}}</span><span v-if="lastFrame?.bindingSeq">seq {{lastFrame.bindingSeq}}</span></div></div></template>
